#!/usr/bin/env python3
"""Decode the scrambled app.js from low-tide.chal.csaw.io"""

def rot47(s):
    out = []
    for c in s:
        o = ord(c)
        if 33 <= o <= 126:
            out.append(chr(33 + ((o - 33 + 47) % 94)))
        else:
            out.append(c)
    return ''.join(out)

with open('/home/ctfplayer/workspace/recon/app.js', 'r', encoding='utf-8', errors='replace') as f:
    lines = f.read().split('\n')

for i, line in enumerate(lines):
    print(f"--- line {i} ---")
    print(repr(line))
    print("ROT47:", repr(rot47(line)))
    print()

