"""Probe sid exhaustion mechanics on the low-tide gateway."""
import requests

URL = "http://low-tide-lb.ctf.csaw.io:8080/station/checkin"
UA = "StationSync-Agent/2.1"

def probe(sid, token="abc"):
    r = requests.post(URL, headers={"User-Agent": UA},
                      cookies={"sid": sid},
                      data={"action": "checkin", "token": token},
                      timeout=5)
    return r.json()

if __name__ == "__main__":
    for sid in ("1111111111111111", "2222222222222222"):
        print(f"=== sid={sid} ===")
        for i in range(6):
            print(i, probe(sid))
        print()

