#!/usr/bin/env python3
"""Probe the token check semantics on the low-tide gateway."""
import requests

URL = "http://low-tide-lb.ctf.csaw.io:8080/station/checkin"
UA = {"User-Agent": "StationSync-Agent/2.1"}

def post(sid=None, data=None):
    kw = {"headers": UA, "data": data or {}, "timeout": 5}
    if sid is not None:
        kw["cookies"] = {"sid": sid}
    return requests.post(URL, **kw).json()

if __name__ == "__main__":
    # 1) same sid, different tokens
    sid = "deadbeefdeadbeef"
    print("=== same sid, different tokens ===")
    for t in ("abc", "def", "abc", "def"):
        print(t, post(sid, {"action": "checkin", "token": t}).get("sync_time"))
    # 2) different sids, same token
    print("=== different sids, same token ===")
    for sid in ("deadbeefdeadbeef", "cafebabecafebabe"):
        print(sid, post(sid, {"action": "checkin", "token": "abc"}).get("sync_time"))
    # 3) no token
    print("=== no token ===")
    print(post(None, {"action": "checkin"}))

